  ctx.fillStyle="#2b3d43";ctx.fillRect(x-25,y-12,50,29);
  ctx.strokeStyle="#c89172";ctx.lineWidth=1.5;ctx.beginPath();
  for(let j=-19;j<=19;j+=7){ctx.moveTo(x+j,y-12);ctx.lineTo(x+j,y+17);}ctx.stroke();
