 const left=phase==="open"?Math.ceil(h.pressure/deepPressureRate()*10)/10:0;
 const title=phase==="armed"?(warned?"深井预告 · 碰到石头才开闸":"深井 +500 · 钩住拦路石启动"):phase==="closed"?"关闸 · 深井奖矿已错过":phase==="secured"?"奖矿已钩住 · 回收中":"深井 +500 · 约 "+left.toFixed(1)+" 秒关闸";
