function installTwoShaftBoard(){
  // All positions use unchanged hook origin/units. Fixed first-level lab on desktop only.
  if(Game.difficulty!=="easy"||Game.lightHaul||Game.dualContract||W<540||H<500)return false;
  const hook=newHook(), word="ORE";
  const make=(kind, deg,d,r,weight,value,layer,index)=>{
    const a=deg*Math.PI/180, x=hook.x+Math.cos(a)*d,y=hook.y+Math.sin(a)*d;
    return {kind,x,y,r,weight,value,wobble:0,homeX:x,homeY:y,layer,...(kind==="letter"?{index,letter:word[index]}:{})};
  };
  Game.word={en:word,zh:"矿石",progress:0};Game.lastWord=word;Game.quota=450;
  Game.items=[
    make("letter",46,126,19,1,120,"word",0),make("letter",73,124,19,1,140,"word",1),
    make("letter",139,130,19,1,160,"word",2),
    make("gold",55,220,16,1.4,122,"shared"),make("gold",124,217,16,1.4,122,"shared"),
    make("gold",36,193,16,1.4,122,"ledge"),make("rock",112,217,17,300/122,-50,"ledge"),
    make("rock",94,151,23,3.15,-50,"barrier"),make("diamond",94,306,14,1.2,500,"deep"),
  ];
  initDeepHatch();return true;
}
function drawTwoShaftDetails(){
  if(Game.contractName!=="岔层矿井"||Game.level!==1||Game.state!=="playing"||Game.hook.state!=="swing"||Game.contractTimer>0||Game.timeLeft<=0)return;
  const gate=Game.items.find(i=>i.layer==="barrier"&&!i.grabbed), rich=Game.items.find(i=>i.layer==="deep"&&!i.grabbed);
  if(!gate&&!rich)return;
  ctx.save();ctx.font="bold 12px system-ui, sans-serif";ctx.textAlign="center";ctx.textBaseline="bottom";
  // Mark the deeper floor, not the launch line; the items are drawn afterwards.
  if(W>=620&&H>=500){
    const shelfY=Game.hook.y+264;
    ctx.strokeStyle="rgba(132,163,182,.30)";ctx.lineWidth=1;
    ctx.beginPath();ctx.moveTo(32,shelfY);ctx.lineTo(W/2-65,shelfY);
    ctx.moveTo(W/2+65,shelfY);ctx.lineTo(W-32,shelfY);ctx.stroke();
    ctx.fillStyle="#dfc391";ctx.fillText("浅层侧脉",106,shelfY-8);
    ctx.fillStyle="#a5cdd8";ctx.fillText("深井",W-105,shelfY+23);
  }
  function edge(item,color){
    if(!item)return;
    ctx.strokeStyle=color;ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(item.x,item.y,item.r+5,.16,Math.PI-.16);ctx.stroke();
  }
  for(const ore of Game.items)if(ore.layer==="ledge"&&!ore.grabbed)edge(ore,"#f5cc78");
  edge(gate,"#f3a36d");edge(rich,gate?"#839abb":"#7cdaf3");
  ctx.restore();
}

