let returnedWrongLetter=null;
function wrongOrderLetter(item,game){
  const word=game.word, next=word?.en[word.progress];
  if(!item||item.kind!=="letter"||!next||item.index<=word.progress)return null;
  return {caught:`第${item.index+1}格「${item.letter}」`,next:`第${word.progress+1}格「${next}」`};
}
function letterOrderAdvice(game,target,returnView,aimView){
  if(game.state!=="playing"||game.timeLeft<=0||game.contractTimer>0)return null;
  const hook=game.hook;
  const risk=view=>view?.urgency==="late"?" · 可能超时":view?.urgency==="tight"?" · 时间紧":"";
  const held=hook?.state==="retract"?wrongOrderLetter(hook.grabbed,game):null;
  if(held)return {phase:"held",text:`错抓${held.caught} · 收回不计，X 无效${risk(returnView)}`};
  if(hook?.state!=="swing")return null;
  const receipt=returnedWrongLetter;
  if(receipt&&receipt.word===game.word&&receipt.progress===game.word.progress&&receipt.until>game.time)
    return {phase:"returned",text:`${receipt.caught}已放回 · 先抓${receipt.next}`};
  const aim=wrongOrderLetter(target,game);
  if(aim&&!target.grabbed)return {phase:"aim",text:`错序${aim.caught} · 先抓${aim.next}${risk(aimView)}`};
  return null;
}

function rememberWrongLetterReturn(item){
  const order=wrongOrderLetter(item,Game);
  if(order)returnedWrongLetter={...order,word:Game.word,progress:Game.word.progress,until:Game.time+1.8};
}

