let bombScoreReceipt=null;
function presentBombDelivery(previousScore,x,y){
  const loss=previousScore-Game.score;
  floatText(loss?"−"+loss+"分":"不扣分",x,y,"#f97316");
  showBombReceipt("炸弹送达："+(loss?"实扣"+loss+"分":"不扣分")+" · 矿收、钱包不变");
}
function zeroBombDecision(game, budget, count){
  if(!budget||!budget.canDiscard||budget.urgency!=="normal"||game.hook?.grabbed?.kind!=="bomb"||game.score!==0||count<=0)return null;
  return {
    reference:budget.reference.replace("炸弹 送达扣0分","炸弹送达不扣分").replace("X可放弃","X耗1管，不防扣分"),
    announcement:"炸弹送达不扣分。按 X 仍会消耗一根雷管。"
  };
}
function showBombReceipt(text){
  bombScoreReceipt={word:Game.word,until:Game.time+2.2,text};
}
function updateBombReceipt(){
  const node=$id("bomb-receipt");
  if(!node)return;
  const active=Game.state==="playing"&&bombScoreReceipt&&bombScoreReceipt.word===Game.word&&bombScoreReceipt.until>Game.time;
  const text=active?bombScoreReceipt.text:"";
  if(node.textContent!==text)node.textContent=text;
  node.hidden=!text;
}
